import { useSearchParams } from "react-router-dom";
import { DEVELOPER, NUMBER, USER, AGE, SINGLE } from "./actionTypes";
import { useState } from "react";
import Modal from "./components/Modal/Modal";

export const initialState = {
  developers: [],
  user: { id: 1, name: "Mary" },
  arr: [1, 34, 2],
};

const [toggle, setToggle] = useState(false);

function openClose() {
  setToggle(!toggle);
}

function reducer(state = initialState, action) {
  switch (action.type) {
    case NUMBER:
      if (isNaN(Number(action.payload))) {
        openClose()
        {toggle? <Modal /> : null}
      } else {
        return { ...state, arr: [...state.arr, action.payload] };
      }

    case AGE:
      return { ...state, user: { ...state.user, age: action.payload } };
    case DEVELOPER:
      return { ...state, developers: [...state.developers, action.payload] };
    case USER:
      return {
        ...state,
        user: { id: state.user.id + 1, name: action.payload },
      };
    case SINGLE:
      let newArr = state.arr.filter((elm) => {
        return elm > 9;
      });
      return { ...state, arr: newArr };
    default:
      return state;
  }
}

export default reducer;
